#!/usr/bin/env python3
"""
Round 135b (culprits-tiles-more), 2 October 2026.

food_system.py (new): Who Owns the Food Industry, the page's whole data, as
food/system.places.geojson and food/system.boxes.json; a first build is included.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/food_system.py': '', 'food/system.places.geojson': '', 'food/system.boxes.json': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round135b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round135b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
